import{_ as i}from"./chunks/00-sidebar-overview.Cutxsm52.js";import{_ as a}from"./chunks/01-files-browse.Cukccd-5.js";import{_ as t,o as e,c as n,a2 as l}from"./chunks/framework.D4up2k3b.js";const F=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":null}'),h={name:"guide/quick-start.md"};function p(r,s,d,o,k,g){return e(),n("div",null,[...s[0]||(s[0]=[l('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>大约四步：下载 → 初始化 Hub → 启动 Hub → 初始化并连接 Agent。完成后在浏览器里登录、Add Root，即可浏览。</p><p><img src="'+i+`" alt="侧栏与 Files 总览"></p><h2 id="_1-下载" tabindex="-1">1. 下载 <a class="header-anchor" href="#_1-下载" aria-label="Permalink to &quot;1. 下载&quot;">​</a></h2><p>从 <a href="https://github.com/ZhimingYe/filebox/releases/latest" target="_blank" rel="noreferrer">Releases</a> 取最新 musl 静态包：</p><ul><li><code>filebox-hub-&lt;ver&gt;-x86_64-musl.tar.gz</code> — 放在你能暴露 HTTPS 的机器上</li><li><code>filebox-agent-&lt;ver&gt;-x86_64-musl.tar.gz</code> — 放在每台要浏览的后端机上</li></ul><p>多数用户不需要从源码编译。</p><h2 id="_2-初始化并启动-hub" tabindex="-1">2. 初始化并启动 Hub <a class="header-anchor" href="#_2-初始化并启动-hub" aria-label="Permalink to &quot;2. 初始化并启动 Hub&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filebox-hub-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-x86_64-musl.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filebox-hub-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/hub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init-config</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 监听地址、管理员账号、Agent token（只打印一次）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/hub</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # 默认 :3000，自带前端静态资源</span></span></code></pre></div><p><code>--init-config</code> 会生成 <code>config/hub.json</code>，并<strong>只打印一次</strong> Agent token（Hub 只存 bcrypt hash）。请立刻保存 token，之后无法从 Hub 再读出明文。</p><p>生产环境请在前面加 nginx / Caddy / Traefik 终止 TLS。详见 <a href="/filebox/docs/ops/hub">Hub 配置与 HTTPS</a>。</p><h2 id="_3-初始化并启动-agent" tabindex="-1">3. 初始化并启动 Agent <a class="header-anchor" href="#_3-初始化并启动-agent" aria-label="Permalink to &quot;3. 初始化并启动 Agent&quot;">​</a></h2><p>在后端机上：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filebox-agent-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-x86_64-musl.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filebox-agent-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init-config</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 粘贴 Hub 打印的 token，填写 Hub URL（https://…）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span></span></code></pre></div><p>也可用环境变量（适合 systemd / 容器）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FILEBOX_AGENT_HUB</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://filebox.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FILEBOX_AGENT_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;the-token-from-hub&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FILEBOX_AGENT_NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hpc-node-01&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FILEBOX_AGENT_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/var/lib/filebox&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span></span></code></pre></div><p>Agent <strong>只出站</strong>；防火墙无需为它开入站。连上后侧栏会出现该机器。</p><h2 id="_4-登录并添加根目录" tabindex="-1">4. 登录并添加根目录 <a class="header-anchor" href="#_4-登录并添加根目录" aria-label="Permalink to &quot;4. 登录并添加根目录&quot;">​</a></h2><ol><li>浏览器打开 Hub URL，用 <code>--init-config</code> 时设置的账号登录。</li><li>侧栏应出现已连接的 Agent。</li><li><strong>Settings → Add Root</strong>，填绝对路径或 <code>~/…</code>。</li><li>进入 <strong>Files</strong> 开始浏览。</li></ol><p><img src="`+a+'" alt="文件浏览"></p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想做…</th><th>去看</th></tr></thead><tbody><tr><td>更细的 Hub / HTTPS</td><td><a href="./install-hub">部署 Hub</a> · <a href="/filebox/docs/ops/hub">Hub 运维</a></td></tr><tr><td>多机 Agent、环境变量</td><td><a href="./install-agent">部署 Agent</a> · <a href="/filebox/docs/ops/agent">Agent 运维</a></td></tr><tr><td>首次登录与各视图</td><td><a href="./first-login">首次登录与添加目录</a></td></tr><tr><td>搜索 / 合集 / 传输 / 终端</td><td><a href="/filebox/docs/features/browse">功能导览</a></td></tr><tr><td>Word / PPT / Excel 预览</td><td><a href="/filebox/docs/ops/office">Office 预览</a></td></tr></tbody></table>',22)])])}const f=t(h,[["render",p]]);export{F as __pageData,f as default};
